      { t = "Bebe el agua de los videntes junto a la hoguera del pueblo y sigue la visión hasta Profeta Velocisabio, al noroeste. Entrégala y acepta [Rito de la Sabiduría].", wp = { { m = 1412, z = "Mulgore", x = 34.3, y = 43.3, n = "Entregar: Rito de la Visión (Profeta Velocisabio)", q = 772, a = "T" }, { m = 1412, z = "Mulgore", x = 34.3, y = 43.3, n = "Recoger: Rito de la Sabiduría (Profeta Velocisabio)", q = 773, a = "A" } } },
