      { t = "Al este del camino, en la caravana devastada, abre el cajón de provisiones sellado: entrega [La caravana devastada] y acepta [La caravana devastada].", wp = { { m = 1412, z = "Mulgore", x = 51.9, y = 53.4, n = "Entregar: La caravana devastada (Cajón de provisiones sellado)", q = 749, a = "T" }, { m = 1412, z = "Mulgore", x = 51.9, y = 53.4, n = "Recoger: La caravana devastada (Cajón de provisiones sellado)", q = 751, a = "A" } } },
      { t = "Vuelve al pueblo: entrega [El tótem de Tronacuerno] y acepta [La purificación de Tronacuerno]; entrega [La caza de los aguilones], [Mazzranache] y [Una excavación de los enanos]. Al este del pueblo, entrega [La caravana devastada] a Morin Acechanubes y acepta [Los Ventura y Cía.] y [Supervisor Fizsprocket].", wp = { { m = 1412, z = "Mulgore", x = 47.5, y = 63.6, n = "Entregar: El tótem de Tronacuerno (Mull Tronacuerno)", q = 756, a = "T" }, { m = 1412, z = "Mulgore", x = 47.5, y = 63.6, n = "Recoger: La purificación de Tronacuerno (Mull Tronacuerno)", q = 758, a = "A" }, { m = 1412, z = "Mulgore", x = 47.7, y = 62.7, n = "Entregar: La caza de los aguilones (Harken Tótem de Viento)", q = 761, a = "T" }, { m = 1412, z = "Mulgore", x = 46.2, y = 60.8, n = "Entregar: Mazzranache (Maur Clamalluvias)", q = 766, a = "T" }, { m = 1412, z = "Mulgore", x = 46.7, y = 63.4, n = "Entregar: Una excavación de los enanos (Baine Pezuña de Sangre)", q = 746, a = "T" }, { m = 1412, z = "Mulgore", x = 54.8, y = 64.3, n = "Entregar: La caravana devastada (Morin Acechanubes)", q = 751, a = "T" }, { m = 1412, z = "Mulgore", x = 54.8, y = 64.3, n = "Recoger: Los Ventura y Cía. (Morin Acechanubes)", q = 764, a = "A" }, { m = 1412, z = "Mulgore", x = 54.8, y = 64.3, n = "Recoger: Supervisor Fizsprocket (Morin Acechanubes)", q = 765, a = "A" } } },
      { t = "Nivel 10: entrena con Yaw Crinafilada: Aspecto del halcón y Picadura de serpiente (rango 2). Acepta su misión de clase, [Domesticar la bestia]. Skorn Nubeblanca, en el pueblo, te da [Los hábitos del cazador]. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1412, z = "Mulgore", x = 46.9, y = 59.6, n = "Yaw Crinafilada", npc = 3065 }, { m = 1412, z = "Mulgore", x = 46.9, y = 59.6, n = "Recoger: Domesticar la bestia (Yaw Crinafilada)", q = 6061, a = "A" }, { m = 1412, z = "Mulgore", x = 46.0, y = 63.4, n = "Recoger: Los hábitos del cazador (Skorn Nubeblanca)", q = 861, a = "A" } }, comprobar = { hechizos = { 13165 } } },
      { t = "Al oeste del pueblo usa la <Fusta de domador> con un Zancudo de llanura adulto y no lo ataques mientras la usas: al acabar, lo has domado. Vuelve con Yaw Crinafilada, entrégala y acepta [Domesticar la bestia].", wp = { { m = 1412, z = "Mulgore", x = 41.3, y = 69.0, n = "Objetivo: Domesticar la bestia", q = 6061, a = "C" }, { m = 1412, z = "Mulgore", x = 46.9, y = 59.6, n = "Entregar: Domesticar la bestia (Yaw Crinafilada)", q = 6061, a = "T" }, { m = 1412, z = "Mulgore", x = 46.9, y = 59.6, n = "Recoger: Domesticar la bestia (Yaw Crinafilada)", q = 6087, a = "A" } } },
      { t = "Al nordeste, en la mina de los Ventura y Cía.: mata trabajadores y controladores para [Los Ventura y Cía.]. Dentro, el supervisor Fizsprocket suelta su sujetapapeles ([Supervisor Fizsprocket]) y unas páginas: léelas para [Las notas de Fizsprocket] y recoge las demás dentro de la mina.", wp = { { m = 1412, z = "Mulgore", x = 59.3, y = 47.7, n = "Objetivo: Los Ventura y Cía.", q = 764, a = "C" }, { m = 1412, z = "Mulgore", x = 61.2, y = 49.3, n = "Objetivo: Supervisor Fizsprocket", q = 765, a = "C" }, { m = 1412, z = "Mulgore", x = 61.2, y = 49.3, n = "Fizsprocket", q = 98424, a = "A" }, { m = 1412, z = "Mulgore", x = 59.8, y = 47.0, n = "Objetivo: Las notas de Fizsprocket", q = 98424, a = "C" } } },
      { t = "Al oeste, junto al camino del norte, usa el tótem en el Pozo Tronacuerno ([La purificación de Tronacuerno]). Por las llanuras de alrededor doma un Acechador de pradera con la <Fusta de domador> ([Domesticar la bestia]).", wp = { { m = 1412, z = "Mulgore", x = 44.2, y = 51.1, n = "Pozo Tronacuerno", q = 758, a = "C" }, { m = 1412, z = "Mulgore", x = 47.1, y = 49.1, n = "Objetivo: Domesticar la bestia", q = 6087, a = "C" } } },
      { t = "Vuelve al pueblo: entrega [La purificación de Tronacuerno] y acepta [El tótem Ferocrín]; entrega [Domesticar la bestia] a Yaw Crinafilada y acepta [Domesticar la bestia]. Al este, entrega [Los Ventura y Cía.], [Supervisor Fizsprocket] y [Las notas de Fizsprocket] a Morin Acechanubes y acepta [Fin de las operaciones].", wp = { { m = 1412, z = "Mulgore", x = 47.5, y = 63.6, n = "Entregar: La purificación de Tronacuerno (Mull Tronacuerno)", q = 758, a = "T" }, { m = 1412, z = "Mulgore", x = 47.5, y = 63.6, n = "Recoger: El tótem Ferocrín (Mull Tronacuerno)", q = 759, a = "A" }, { m = 1412, z = "Mulgore", x = 54.8, y = 64.3, n = "Entregar: Los Ventura y Cía. (Morin Acechanubes)", q = 764, a = "T" }, { m = 1412, z = "Mulgore", x = 54.8, y = 64.3, n = "Entregar: Supervisor Fizsprocket (Morin Acechanubes)", q = 765, a = "T" }, { m = 1412, z = "Mulgore", x = 54.8, y = 64.3, n = "Entregar: Las notas de Fizsprocket (Morin Acechanubes)", q = 98424, a = "T" }, { m = 1412, z = "Mulgore", x = 54.8, y = 64.3, n = "Recoger: Fin de las operaciones (Morin Acechanubes)", q = 98427, a = "A" }, { m = 1412, z = "Mulgore", x = 46.9, y = 59.6, n = "Entregar: Domesticar la bestia (Yaw Crinafilada)", q = 6087, a = "T" }, { m = 1412, z = "Mulgore", x = 46.9, y = 59.6, n = "Recoger: Domesticar la bestia (Yaw Crinafilada)", q = 6088, a = "A" } } },
      { t = "Al este, cerca del borde de Mulgore: mata lobos alfa de pradera por los colmillos de [El tótem Ferocrín], y centauros y avanzados Galak para [Expúlsalos]; Herak el Saqueador lleva la cabeza.", wp = { { m = 1412, z = "Mulgore", x = 60.7, y = 65.1, n = "Objetivo: El tótem Ferocrín", q = 759, a = "C" }, { m = 1412, z = "Mulgore", x = 62.6, y = 62.0, n = "Objetivo: Expúlsalos", q = 99080, a = "C" } } },
      { t = "Vuelve al pueblo: entrega [El tótem Ferocrín] y acepta [La purificación de Bravacrín]. Entrega [Expúlsalos] a Baine Pezuña de Sangre y acepta [El Gran Jefe].", wp = { { m = 1412, z = "Mulgore", x = 47.5, y = 63.6, n = "Entregar: El tótem Ferocrín (Mull Tronacuerno)", q = 759, a = "T" }, { m = 1412, z = "Mulgore", x = 47.5, y = 63.6, n = "Recoger: La purificación de Bravacrín (Mull Tronacuerno)", q = 760, a = "A" }, { m = 1412, z = "Mulgore", x = 46.7, y = 63.4, n = "Entregar: Expúlsalos (Baine Pezuña de Sangre)", q = 99080, a = "T" }, { m = 1412, z = "Mulgore", x = 46.7, y = 63.4, n = "Recoger: El Gran Jefe (Baine Pezuña de Sangre)", q = 99082, a = "A" } } },
      { t = "De camino al norte, por las llanuras del centro de Mulgore, doma un Aguilón con la <Fusta de domador> ([Domesticar la bestia]).", wp = { { m = 1412, z = "Mulgore", x = 49.3, y = 46.6, n = "Objetivo: Domesticar la bestia", q = 6088, a = "C" } } },
      { t = "Al norte de la mina, coge la llave de la cortadora ([Fin de las operaciones]). Sigue al norte hasta las Rocas Rojas: Espíritu ancestral recibe [Rito de la Sabiduría] y te da [Viaje a Cima del Trueno]. Tradicionalista Totemlluvia, al lado, te da [Cementerio sagrado]: mata intrusos Lomopelo por las rocas y entrégala.", wp = { { m = 1412, z = "Mulgore", x = 56.8, y = 42.8, n = "Objetivo: Fin de las operaciones", q = 98427, a = "C" }, { m = 1412, z = "Mulgore", x = 58.3, y = 30.7, n = "Entregar: Rito de la Sabiduría (Espíritu ancestral)", q = 773, a = "T" }, { m = 1412, z = "Mulgore", x = 58.3, y = 30.7, n = "Recoger: Viaje a Cima del Trueno (Espíritu ancestral)", q = 775, a = "A" }, { m = 1412, z = "Mulgore", x = 57.0, y = 34.5, n = "Recoger: Cementerio sagrado (Tradicionalista Totemlluvia)", q = 833, a = "A" }, { m = 1412, z = "Mulgore", x = 58.1, y = 30.8, n = "Objetivo: Cementerio sagrado", q = 833, a = "C" }, { m = 1412, z = "Mulgore", x = 57.0, y = 34.5, n = "Entregar: Cementerio sagrado (Tradicionalista Totemlluvia)", q = 833, a = "T" } } },
      { t = "Al oeste de las Rocas Rojas, por las llanuras del norte, mata merodeadores de las estepas por las garras de [Los hábitos del cazador]. Junto a Cima del Trueno, usa el tótem en el Pozo Bravacrín ([La purificación de Bravacrín]).", wp = { { m = 1412, z = "Mulgore", x = 50.7, y = 31.7, n = "Objetivo: Los hábitos del cazador", q = 861, a = "C" }, { m = 1412, z = "Mulgore", x = 42.7, y = 25.0, n = "Pozo Bravacrín", q = 760, a = "C" } } },

