  {
    titulo = "Cima del Trueno", min = 10, max = 12,
    entrenar = "En Cima del Trueno tus instructores de cazador están en la Elevación de los Cazadores (sur de la ciudad): Kary Tronacuerno, Holt Tronacuerno y Urek Tronacuerno, y Hesuwa Tronacuerno enseña a tu mascota. Más adelante entrenarás en Orgrimmar o aquí: venden lo mismo.",
    equipo = "En Cima del Trueno, Hogor Pezuñatrueno vende armas de fuego y munición.",
    profesion = "Si llevas 50 de minería o de desuello, aprende aquí el rango oficial: Brek Pezuñapétrea (Minería) y Mooranta (Desuello).",
    pasos = {
      { t = "Sube a Cima del Trueno por el ascensor. Activa el vuelo con Tal. En el centro de la ciudad entrega [Viaje a Cima del Trueno], [Los Caminantes Lejanos] y [El Gran Jefe] a Cairne Pezuña de Sangre.", wp = { { m = 1456, z = "Cima del Trueno", x = 47.0, y = 49.8, n = "Tal", npc = 2995 }, { m = 1456, z = "Cima del Trueno", x = 60.3, y = 51.7, n = "Entregar: Viaje a Cima del Trueno (Cairne Pezuña de Sangre)", q = 775, a = "T" }, { m = 1456, z = "Cima del Trueno", x = 60.3, y = 51.7, n = "Entregar: Los Caminantes Lejanos (Cairne Pezuña de Sangre)", q = 98430, a = "T" }, { m = 1456, z = "Cima del Trueno", x = 60.3, y = 51.7, n = "Entregar: El Gran Jefe (Cairne Pezuña de Sangre)", q = 99082, a = "T" } }, comprobar = { vuelo = "Cima del Trueno" } },
      { t = "Al este, en la Elevación de los Ancestros, Archidruida Hamuul Runatótem te da [El oasis de Los Baldíos]: se entrega en El Cruce.", wp = { { m = 1456, z = "Cima del Trueno", x = 78.6, y = 28.6, n = "Recoger: El oasis de Los Baldíos (Archidruida Hamuul Runatótem)", q = 886, a = "A" } } },
      { t = "Al sur de la ciudad, en la Elevación de los Cazadores, entrega [Los hábitos del cazador] a Melor Pezuñapétrea y acepta [Sergra Espinoscura].", wp = { { m = 1456, z = "Cima del Trueno", x = 61.5, y = 80.9, n = "Entregar: Los hábitos del cazador (Melor Pezuñapétrea)", q = 861, a = "T" }, { m = 1456, z = "Cima del Trueno", x = 61.5, y = 80.9, n = "Recoger: Sergra Espinoscura (Melor Pezuñapétrea)", q = 860, a = "A" } } },
      { t = "Baja de Cima del Trueno y sigue el camino al sur hasta el Pueblo Pezuña de Sangre: entrega [La purificación de Bravacrín] a Mull Tronacuerno y acepta [El informe de Tronacuerno] (se entrega en Cima del Trueno: lo harás al volver). Entrega [Domesticar la bestia] a Yaw Crinafilada: aprendes Domesticar bestia, Llamar a mascota y Retirar mascota. Acepta [Entrenar a la bestia]. Doma tu mascota: un Acechador de pradera o un lobo de pradera te van bien. Al este del pueblo, entrega [Fin de las operaciones] a Morin Acechanubes.", wp = { { m = 1412, z = "Mulgore", x = 47.5, y = 63.6, n = "Entregar: La purificación de Bravacrín (Mull Tronacuerno)", q = 760, a = "T" }, { m = 1412, z = "Mulgore", x = 47.5, y = 63.6, n = "Recoger: El informe de Tronacuerno (Mull Tronacuerno)", q = 98435, a = "A" }, { m = 1412, z = "Mulgore", x = 54.8, y = 64.3, n = "Entregar: Fin de las operaciones (Morin Acechanubes)", q = 98427, a = "T" }, { m = 1412, z = "Mulgore", x = 46.9, y = 59.6, n = "Entregar: Domesticar la bestia (Yaw Crinafilada)", q = 6088, a = "T" }, { m = 1412, z = "Mulgore", x = 46.9, y = 59.6, n = "Recoger: Entrenar a la bestia (Yaw Crinafilada)", q = 6089, a = "A" } } },
      { t = "Sal de Mulgore por el camino del este hacia Los Baldíos y síguelo hasta el Campamento Taurajo: activa el vuelo con Omusa Tronacuerno. Después sigue el camino al norte hasta El Cruce.", wp = { { m = 1413, z = "Los Baldíos", x = 44.5, y = 59.1, n = "Omusa Tronacuerno", npc = 10378 } }, comprobar = { vuelo = "Taurajo" } },

