  {
    titulo = "Los Baldíos: El Cruce y el Vigía Lejano", min = 11, max = 14,
    entrenar = "En Los Baldíos no hay instructor de cazador: vuelve a Orgrimmar cada dos niveles, en vuelo desde El Cruce (Ormak (Ormak Tirosiniestro) y Xao'tsu (Xao'tsu, mascotas), en el Valle de los Espíritus de Orgrimmar). Primer talento al 10: Bestias > Aspectos letales. Al 12 aprende Aliviar mascota (cura a tu mascota) y Cortar alas.",
    equipo = "En El Cruce, Uthrok vende arcos, flechas y munición. Las misiones de El Cruce dan cuero y botas.",
    profesion = "Los zancudos, leones y astacebras de Los Baldíos dan cuero ligero y medio. Las vetas de cobre y de estaño están en los montes del norte. Pon la piedra de hogar en El Cruce.",
    pasos = {
      { t = "En El Cruce entrega [Sergra Espinoscura] a Sergra Espinoscura y acepta [La amenaza de los zancudos de llanura]; entrega [El oasis de Los Baldíos] a Tonga Tótem de Runa y acepta [Las Charcas del Olvido]. Acepta también [Acabar con los ataques de los Crines de Acero] y [Suministros para El Cruce] (Thork), [Los raptores ladrones] (Gazrog) y [Esporas de hongos] (Boticario Helbrim). Pon la piedra de hogar con Tabernero Boorand Ventollano y activa el vuelo con Devrak.", wp = { { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Entregar: Sergra Espinoscura (Sergra Espinoscura)", q = 860, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: La amenaza de los zancudos de llanura (Sergra Espinoscura)", q = 844, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Entregar: El oasis de Los Baldíos (Tonga Tótem de Runa)", q = 886, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Recoger: Las Charcas del Olvido (Tonga Tótem de Runa)", q = 870, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Recoger: Acabar con los ataques de los Crines de Acero (Thork)", q = 871, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Recoger: Suministros para El Cruce (Thork)", q = 5041, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.9, y = 30.3, n = "Recoger: Los raptores ladrones (Gazrog)", q = 869, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.4, y = 30.1, n = "Recoger: Esporas de hongos (Boticario Helbrim)", q = 848, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.0, y = 29.9, n = "Tabernero Boorand Ventollano", npc = 3934 }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.3, n = "Devrak", npc = 3615 } }, comprobar = { vuelo = "El Cruce" } },
      { t = "Jahan Ala Halcón, en El Cruce, te da [Un fardo de pieles]: entrégala a Devrak, al lado, y acepta [Un viaje a Cima del Trueno]. Vuela a Cima del Trueno y lleva el fardo a Ahanu; te manda con Tal, que te da [Volver junto a Jahan]. Entrega también [El informe de Tronacuerno] a Archidruida Hamuul Runatótem y [Entrenar a la bestia] a Holt Tronacuerno, en la Elevación de los Cazadores: aprendes Alimentar mascota, Revivir mascota y Adiestramiento de bestias. Vuelve en vuelo a El Cruce y entrega [Volver junto a Jahan] a Jahan Ala Halcón.", wp = { { m = 1413, z = "Los Baldíos", x = 51.2, y = 29.1, n = "Recoger: Un fardo de pieles (Jahan Ala Halcón)", q = 6361, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.3, n = "Entregar: Un fardo de pieles (Devrak)", q = 6361, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.3, n = "Recoger: Un viaje a Cima del Trueno (Devrak)", q = 6362, a = "A" }, { m = 1456, z = "Cima del Trueno", x = 45.8, y = 55.8, n = "Entregar: Un viaje a Cima del Trueno (Ahanu)", q = 6362, a = "T" }, { m = 1456, z = "Cima del Trueno", x = 45.8, y = 55.8, n = "Recoger: Tal, maestro de jinetes del viento (Ahanu)", q = 6363, a = "A" }, { m = 1456, z = "Cima del Trueno", x = 47.0, y = 49.8, n = "Entregar: Tal, maestro de jinetes del viento (Tal)", q = 6363, a = "T" }, { m = 1456, z = "Cima del Trueno", x = 47.0, y = 49.8, n = "Recoger: Volver junto a Jahan (Tal)", q = 6364, a = "A" }, { m = 1456, z = "Cima del Trueno", x = 78.6, y = 28.6, n = "Entregar: El informe de Tronacuerno (Archidruida Hamuul Runatótem)", q = 98435, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.2, y = 29.1, n = "Entregar: Volver junto a Jahan (Jahan Ala Halcón)", q = 6364, a = "T" }, { m = 1456, z = "Cima del Trueno", x = 57.3, y = 89.8, n = "Entregar: Entrenar a la bestia (Holt Tronacuerno)", q = 6089, a = "T" } } },
      { t = "Sigue el camino al nordeste hasta el Puesto del Vigía Lejano y cruza el puente a Durotar. Sube al norte hasta Orgrimmar (puerta del sur) y activa el vuelo con Doras, en la torre del Valle de la Fuerza: desde ahí vuelas a entrenar.", wp = { { m = 1454, z = "Orgrimmar", x = 45.1, y = 63.9, n = "Doras", npc = 3310 } }, comprobar = { vuelo = "Orgrimmar" } },
      { t = "De vuelta hacia El Cruce, en los campamentos de los Crines de Acero del nordeste: mata buscaquas, tejespinas y cazadores para [Acabar con los ataques de los Crines de Acero] y recoge los cajones de suministros para [Suministros para El Cruce]. Mata zancudos de llanura para [La amenaza de los zancudos de llanura] por el camino.", wp = { { m = 1413, z = "Los Baldíos", x = 55.3, y = 25.8, n = "Objetivo: Acabar con los ataques de los Crines de Acero", q = 871, a = "C" }, { m = 1413, z = "Los Baldíos", x = 59.0, y = 25.8, n = "Objetivo: Suministros para El Cruce", q = 5041, a = "C" }, { m = 1413, z = "Los Baldíos", x = 53.1, y = 31.3, n = "Objetivo: La amenaza de los zancudos de llanura", q = 844, a = "C" } } },
      { t = "Vuelve a El Cruce: entrega [Acabar con los ataques de los Crines de Acero], [Suministros para El Cruce] y [La amenaza de los zancudos de llanura]. Acepta [El fin de las hostilidades] y [El astacebra].", wp = { { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Entregar: Acabar con los ataques de los Crines de Acero (Thork)", q = 871, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Entregar: Suministros para El Cruce (Thork)", q = 5041, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Entregar: La amenaza de los zancudos de llanura (Sergra Espinoscura)", q = 844, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Recoger: El fin de las hostilidades (Thork)", q = 872, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: El astacebra (Sergra Espinoscura)", q = 845, a = "A" } } },
      { t = "Al noroeste, en las Charcas del Olvido, explora el agua para [Las Charcas del Olvido] y recoge los champiñones de [Esporas de hongos]. Mata astacebras para [El astacebra].", wp = { { m = 1413, z = "Los Baldíos", x = 45.1, y = 22.5, n = "Objetivo: Las Charcas del Olvido", q = 870, a = "C" }, { m = 1413, z = "Los Baldíos", x = 46.6, y = 39.4, n = "Objetivo: Esporas de hongos", q = 848, a = "C" }, { m = 1413, z = "Los Baldíos", x = 52.0, y = 36.4, n = "Objetivo: El astacebra", q = 845, a = "C" } } },
      { t = "De vuelta, mata al jefe Kreenig Gruñucico y a geománticos y defensores Crines de Acero, al este del camino, para [El fin de las hostilidades].", wp = { { m = 1413, z = "Los Baldíos", x = 58.3, y = 25.2, n = "Objetivo: El fin de las hostilidades", q = 872, a = "C" } } },
      { t = "En El Cruce entrega [El fin de las hostilidades], [El astacebra], [Las Charcas del Olvido] y [Esporas de hongos]. Acepta [Merodeadores de los Baldíos] y [El Oasis Estancado].", wp = { { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Entregar: El fin de las hostilidades (Thork)", q = 872, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Entregar: El astacebra (Sergra Espinoscura)", q = 845, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Entregar: Las Charcas del Olvido (Tonga Tótem de Runa)", q = 870, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.4, y = 30.1, n = "Entregar: Esporas de hongos (Boticario Helbrim)", q = 848, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: Merodeadores de los Baldíos (Sergra Espinoscura)", q = 903, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Recoger: El Oasis Estancado (Tonga Tótem de Runa)", q = 877, a = "A" } } },
      { t = "Misión extra para no quedarte corto de nivel: [SE BUSCA: Barón Longavera] (nivel 16). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1413, z = "Los Baldíos", x = 62.6, y = 37.5, n = "Recoger: SE BUSCA: Barón Longavera (SE BUSCA)", q = 895, a = "A" }, { m = 1413, z = "Los Baldíos", x = 63.4, y = 48.6, n = "Objetivo: SE BUSCA: Barón Longavera", q = 895, a = "C" }, { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Entregar: SE BUSCA: Barón Longavera (Gazlowe)", q = 895, a = "T" } } }, -- REFUERZO_97 q=895
      { t = "Misión extra para no quedarte corto de nivel: [Pellejo de los descarriados] (nivel 17). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1413, z = "Los Baldíos", x = 46, y = 35.7, n = "Recoger: Pellejo de los descarriados (Nalpak)", q = 1486, a = "A" }, { m = 1413, z = "Los Baldíos", x = 46, y = 35.7, n = "Entregar: Pellejo de los descarriados (Nalpak)", q = 1486, a = "T" } } }, -- REFUERZO_97 q=1486
      { t = "Nivel 12: vuela a Orgrimmar y entrena con Ormak Tirosiniestro: Disparo Arcano (rango 2), Aliviar mascota y Cortar alas; con Xao'tsu, al lado, Gran aguante (rango 2) y Armadura natural (rango 2) para tu mascota. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1454, z = "Orgrimmar", x = 66.0, y = 18.5, n = "Ormak Tirosiniestro", npc = 3352 }, { m = 1454, z = "Orgrimmar", x = 66.3, y = 14.8, n = "Xao'tsu", npc = 10088 } }, comprobar = { hechizos = { 136 } } },

    },
  },
  {
    titulo = "Los Baldíos: Trinquete y el Oasis", min = 14, max = 18,
    entrenar = "Al 14 no hay nada que haga falta. Al 16, en Orgrimmar: Mordedura de mangosta (solo después de esquivar un ataque) y Golpe de raptor (rango 3). Talentos: 10-14 Aspectos letales y 15-16 Fuego enfocado.",
    equipo = "En Trinquete hay vendedores de armas y armaduras. [El botín robado] da buenas piezas para tu nivel. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuella los leones y los astacebras. Al este, en las vetas de cobre y de estaño del camino a Trinquete, mina lo que veas. En la posada de Trinquete hay una forja para fundir.",
    pasos = {
      { t = "Al este, por el camino de Trinquete: mata raptores para [Los raptores ladrones] y merodeadores de la sabana para [Merodeadores de los Baldíos]. Las cabezas también caen de los raptores de la costa.", wp = { { m = 1413, z = "Los Baldíos", x = 55.8, y = 44.6, n = "Objetivo: Los raptores ladrones", q = 869, a = "C" }, { m = 1413, z = "Los Baldíos", x = 42.7, y = 32.0, n = "Objetivo: Merodeadores de los Baldíos", q = 903, a = "C" } } },
      { t = "En Trinquete activa el vuelo con Bragok y acepta [Los filibusteros del Mar del Sur] (Gazlowe). En la costa sur del pueblo mata brigadieres y cañoneros del Mar del Sur para [Los filibusteros del Mar del Sur].", wp = { { m = 1413, z = "Los Baldíos", x = 63.1, y = 37.2, n = "Bragok", npc = 16227 }, { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Recoger: Los filibusteros del Mar del Sur (Gazlowe)", q = 887, a = "A" }, { m = 1413, z = "Los Baldíos", x = 63.7, y = 46.9, n = "Objetivo: Los filibusteros del Mar del Sur", q = 887, a = "C" } }, comprobar = { vuelo = "Trinquete" } },
      { t = "Entrega [Los filibusteros del Mar del Sur] y acepta [El envío perdido]: llévala a Maestro de muelles Vertipeluca, en el muelle, que te da [El envío perdido]. Entrégala a Gazlowe y acepta [El botín robado]: en el campamento pirata del sur, el envío de botas y las lentes telescópicas.", wp = { { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Entregar: Los filibusteros del Mar del Sur (Gazlowe)", q = 887, a = "T" }, { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Recoger: El envío perdido (Gazlowe)", q = 890, a = "A" }, { m = 1413, z = "Los Baldíos", x = 63.4, y = 38.5, n = "Entregar: El envío perdido (Maestro de muelles Vertipeluca)", q = 890, a = "T" }, { m = 1413, z = "Los Baldíos", x = 63.4, y = 38.5, n = "Recoger: El envío perdido (Maestro de muelles Vertipeluca)", q = 892, a = "A" }, { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Entregar: El envío perdido (Gazlowe)", q = 892, a = "T" }, { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Recoger: El botín robado (Gazlowe)", q = 888, a = "A" }, { m = 1413, z = "Los Baldíos", x = 63.1, y = 49.4, n = "Objetivo: El botín robado", q = 888, a = "C" }, { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Entregar: El botín robado (Gazlowe)", q = 888, a = "T" } } },
      { t = "En la Fisura burbujeante del Oasis Estancado (suroeste de Trinquete) usa el vial para [El Oasis Estancado] y mata quijafortes alterados del agua. Al lado está la plata robada de [La plata robada] (te la da Gazrog al entregar [Los raptores ladrones]).", wp = { { m = 1413, z = "Los Baldíos", x = 55.6, y = 42.8, n = "Objetivo: El Oasis Estancado", q = 877, a = "C" } } },
      { t = "Vuelve a El Cruce: entrega [Los raptores ladrones], [Merodeadores de los Baldíos] y [El Oasis Estancado]. Acepta [La plata robada], [Echeyakee] y [Fuentes de vida].", wp = { { m = 1413, z = "Los Baldíos", x = 51.9, y = 30.3, n = "Entregar: Los raptores ladrones (Gazrog)", q = 869, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Entregar: Merodeadores de los Baldíos (Sergra Espinoscura)", q = 903, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Entregar: El Oasis Estancado (Tonga Tótem de Runa)", q = 877, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.9, y = 30.3, n = "Recoger: La plata robada (Gazrog)", q = 3281, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: Echeyakee (Sergra Espinoscura)", q = 881, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Recoger: Fuentes de vida (Tonga Tótem de Runa)", q = 880, a = "A" } } },
      { t = "Al nordeste, Echeyakee (león blanco) aparece al usar el cuerno en la guarida de los leones ([Echeyakee]).", wp = { { m = 1413, z = "Los Baldíos", x = 55.9, y = 17.2, n = "Objetivo: Echeyakee", q = 881, a = "C" } } },
      { t = "De vuelta al sur, mata quijafortes alterados en los oasis para [Fuentes de vida] y recoge la plata robada del oasis para [La plata robada].", wp = { { m = 1413, z = "Los Baldíos", x = 46.8, y = 39.7, n = "Objetivo: Fuentes de vida", q = 880, a = "C" }, { m = 1413, z = "Los Baldíos", x = 58.0, y = 53.9, n = "Objetivo: La plata robada", q = 3281, a = "C" } } },
      { t = "Entrega en El Cruce [Echeyakee], [Fuentes de vida] y [La plata robada]. Acepta [La ira de los segadores].", wp = { { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Entregar: Echeyakee (Sergra Espinoscura)", q = 881, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Entregar: Fuentes de vida (Tonga Tótem de Runa)", q = 880, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.9, y = 30.3, n = "Entregar: La plata robada (Gazrog)", q = 3281, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: La ira de los segadores (Sergra Espinoscura)", q = 905, a = "A" } } },
      { t = "Misión extra para no quedarte corto de nivel: [La fortuna de un minero] (nivel 18). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1413, z = "Los Baldíos", x = 63.4, y = 38.5, n = "Recoger: La fortuna de un minero (Maestro de muelles Vertipeluca)", q = 896, a = "A" }, { m = 1413, z = "Los Baldíos", x = 60.8, y = 4, n = "Objetivo: La fortuna de un minero", q = 896, a = "C" }, { m = 1413, z = "Los Baldíos", x = 63.4, y = 38.5, n = "Entregar: La fortuna de un minero (Maestro de muelles Vertipeluca)", q = 896, a = "T" } } }, -- REFUERZO_97 q=896
