      { t = "Nivel 28: vuela a Orgrimmar y entrena con Ormak Tirosiniestro: Disparo de puntería (rango 2), Disparo Arcano (rango 4), Aspecto del halcón (rango 3) y Aliviar mascota (rango 3). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1454, z = "Orgrimmar", x = 66.0, y = 18.5, n = "Ormak Tirosiniestro", npc = 3352 } }, comprobar = { hechizos = { 20900 } } },
