  {
    titulo = "El Desierto de Sal", min = 30, max = 32,
    entrenar = "Al 30: Fingir muerte (los enemigos te dejan: para escapar; en Forever, si no lo cancelas, mueres cuando se acaba) y Mordedura de mangosta (rango 2); para tu mascota, Gran aguante (rango 5), Armadura natural (rango 5) y Gruñido (rango 4). Al 32 no hay nada que haga falta. Talentos 31-32: Vínculo espiritual.",
    equipo = "Las misiones de El Desierto de Sal dan buenas recompensas de cuero. En la pista, Synge vende armas de fuego y munición; los arcos y las flechas, Starn en Viento Libre. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello 150+: <Cuero pesado> de las bestias de Las Mil Agujas. Minería 125-175: hierro y oro en las colinas de Las Mil Agujas y de Tanaris.",
    pasos = {
      { t = "Nivel 30: vuela a Orgrimmar y entrena con Ormak Tirosiniestro: Fingir muerte y Mordedura de mangosta (rango 2); con Xao'tsu, Gran aguante (rango 5), Armadura natural (rango 5) y Gruñido (rango 4). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1454, z = "Orgrimmar", x = 66.0, y = 18.5, n = "Ormak Tirosiniestro", npc = 3352 }, { m = 1454, z = "Orgrimmar", x = 66.3, y = 14.8, n = "Xao'tsu", npc = 10088 } }, comprobar = { hechizos = { 5384 } } },
      { t = "Vuela a Viento Libre y sigue al este por Las Mil Agujas hasta El Desierto de Sal.", wp = { { m = 1441, z = "Las Mil Agujas", x = 78.0, y = 77.0, n = "El Desierto de Sal" } }, comprobar = { llegar = 1441 } },
      { t = "En la pista de carreras acepta [Veneno de escórpidos salados], [Caparazones endurecidos], [Menos peso], [Piezas de coches cohete] y [Un bache en la carretera].", wp = { { m = 1441, z = "Las Mil Agujas", x = 78.1, y = 77.1, n = "Recoger: Veneno de escórpidos salados (Fizzle Pernolatón)", q = 1104, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 78.1, y = 77.1, n = "Recoger: Caparazones endurecidos (Wizzle Pernolatón)", q = 1105, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 80.2, y = 75.9, n = "Recoger: Menos peso (Pozík)", q = 1176, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 77.8, y = 77.3, n = "Recoger: Piezas de coches cohete (Kravel Karbarbán)", q = 1110, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 81.6, y = 78.0, n = "Recoger: Un bache en la carretera (Maestro rastreador Zherin)", q = 1175, a = "A" } } },
      { t = "Escórpidos, tortugas, buitres y basiliscos alrededor de la pista; las piezas de coche caen de todo.", wp = { { m = 1441, z = "Las Mil Agujas", x = 73.3, y = 71.0, n = "Objetivo: Veneno de escórpidos salados", q = 1104, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 81.6, y = 55.2, n = "Objetivo: Caparazones endurecidos", q = 1105, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 87.9, y = 65.4, n = "Objetivo: Menos peso", q = 1176, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 79.2, y = 87.1, n = "Objetivo: Piezas de coches cohete", q = 1110, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 78.3, y = 88.0, n = "Objetivo: Un bache en la carretera", q = 1175, a = "C" } } },
      { t = "Entrega todo en la pista.", wp = { { m = 1441, z = "Las Mil Agujas", x = 78.1, y = 77.1, n = "Entregar: Veneno de escórpidos salados (Fizzle Pernolatón)", q = 1104, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 78.1, y = 77.1, n = "Entregar: Caparazones endurecidos (Wizzle Pernolatón)", q = 1105, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 80.2, y = 75.9, n = "Entregar: Menos peso (Pozík)", q = 1176, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 77.8, y = 77.3, n = "Entregar: Piezas de coches cohete (Kravel Karbarbán)", q = 1110, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 81.6, y = 78.0, n = "Entregar: Un bache en la carretera (Maestro rastreador Zherin)", q = 1175, a = "T" } } },

      { t = "Misión extra en otra zona de tu nivel (Laderas de Trabalomas): [Regthar Portamorta] (nivel 32). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1424, z = "Laderas de Trabalomas", x = 63.2, y = 20.7, n = "Recoger: Regthar Portamorta (Krusk)", q = 1361, a = "A" }, { m = 1413, z = "Los Baldíos", x = 45.3, y = 28.4, n = "Entregar: Regthar Portamorta (Regthar Portamorta)", q = 1361, a = "T" } } }, -- REFUERZO_97 q=1361
