  {
    titulo = "Vega de Tuercespina", min = 35, max = 38,
    entrenar = "En Grom'gol están Kragg, instructor de cazador, y Zudd, de mascotas. Al 34: Separación (rango 2) y Picadura de serpiente (rango 5); al 36, Disparo de puntería (rango 3), Disparo Arcano (rango 5) y Aliviar mascota (rango 4). Talentos: 33 Furia desatada (5/5), 34 Entrenamiento de robustez (4/5) y 35-39 Frenesí.",
    equipo = "Reúne las páginas de [Las verdes colinas de Tuercespina] mientras matas: el libro se entrega al 40. En Bahía del Botín, Haren Kanmae vende arcos, flechas y munición. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello 150-225: tigres, panteras y raptores dan <Cuero pesado>. Minería: filones de hierro y oro por toda la Vega.",
    pasos = {
      { t = "Desde Entrañas o desde Orgrimmar coge el zepelín al Campamento Grom'gol (Vega de Tuercespina). Activa el vuelo con Thysta y pon la piedra de hogar con Tabernero Thulbek. Acepta [Caza para Yenniku] (Nimboya), [Collares de huesos sangrientos] y [El Arrecife Mortal] (Kin'weelay), [La defensa de Grom'gol] (Comandante Aggro'gosh) y [El encantamiento de Mok'thardin] (Clarividente Mok'thardin).", wp = { { m = 1434, z = "Vega de Tuercespina", x = 32.5, y = 29.4, n = "Thysta", npc = 1387 }, { m = 1434, z = "Vega de Tuercespina", x = 31.5, y = 29.8, n = "Tabernero Thulbek", npc = 5814 }, { m = 1434, z = "Vega de Tuercespina", x = 32.2, y = 27.7, n = "Recoger: Caza para Yenniku (Nimboya)", q = 581, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 32.3, y = 27.7, n = "Recoger: Collares de huesos sangrientos (Kin'weelay)", q = 596, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 32.3, y = 27.7, n = "Recoger: El Arrecife Mortal (Kin'weelay)", q = 629, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 32.2, y = 28.9, n = "Recoger: La defensa de Grom'gol (Comandante Aggro'gosh)", q = 568, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 32.1, y = 29.2, n = "Recoger: El encantamiento de Mok'thardin (Clarividente Mok'thardin)", q = 570, a = "A" } }, comprobar = { vuelo = "Grom'gol" } },
      { t = "Nivel 34: en Grom'gol entrena con Kragg: Separación (rango 2) y Picadura de serpiente (rango 5). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1434, z = "Vega de Tuercespina", x = 31.2, y = 28.7, n = "Kragg", npc = 1404 } }, comprobar = { hechizos = { 13552 } } },
      { t = "Al norte, en la expedición de Nesingwary: acepta [Bienvenido a la jungla] y entrégala a Hemet Decautela. Acepta [Domina el tigre], [Domina la pantera] y [Domina el raptor].", wp = { { m = 1434, z = "Vega de Tuercespina", x = 35.7, y = 10.5, n = "Recoger: Bienvenido a la jungla (Barnil Jarropetra)", q = 583, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 35.7, y = 10.8, n = "Entregar: Bienvenido a la jungla (Hemet Decautela)", q = 583, a = "T" }, { m = 1434, z = "Vega de Tuercespina", x = 35.6, y = 10.6, n = "Recoger: Domina el tigre (Ajeck Rouack)", q = 185, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 35.5, y = 10.6, n = "Recoger: Domina la pantera (Sir S. J. Erlgadin)", q = 190, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 35.7, y = 10.8, n = "Recoger: Domina el raptor (Hemet Decautela)", q = 194, a = "A" } } },
      { t = "Tigres jóvenes y panteras jóvenes alrededor del campamento.", wp = { { m = 1434, z = "Vega de Tuercespina", x = 35.4, y = 12.0, n = "Objetivo: Domina el tigre", q = 185, a = "C" }, { m = 1434, z = "Vega de Tuercespina", x = 40.2, y = 11.7, n = "Objetivo: Domina la pantera", q = 190, a = "C" }, { m = 1434, z = "Vega de Tuercespina", x = 35.6, y = 10.6, n = "Entregar: Domina el tigre (Ajeck Rouack)", q = 185, a = "T" }, { m = 1434, z = "Vega de Tuercespina", x = 35.5, y = 10.6, n = "Entregar: Domina la pantera (Sir S. J. Erlgadin)", q = 190, a = "T" } } },
      { t = "Segunda parte de tigres y panteras ([Maestría en tigres], [Domina la pantera]) y raptores para [Domina el raptor].", wp = { { m = 1434, z = "Vega de Tuercespina", x = 35.6, y = 10.6, n = "Recoger: Maestría en tigres (Ajeck Rouack)", q = 186, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 35.5, y = 10.6, n = "Recoger: Domina la pantera (Sir S. J. Erlgadin)", q = 191, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 30.7, y = 12.0, n = "Objetivo: Maestría en tigres", q = 186, a = "C" }, { m = 1434, z = "Vega de Tuercespina", x = 29.4, y = 12.6, n = "Objetivo: Domina la pantera", q = 191, a = "C" }, { m = 1434, z = "Vega de Tuercespina", x = 25.8, y = 16.1, n = "Objetivo: Domina el raptor", q = 194, a = "C" }, { m = 1434, z = "Vega de Tuercespina", x = 35.6, y = 10.6, n = "Entregar: Maestría en tigres (Ajeck Rouack)", q = 186, a = "T" }, { m = 1434, z = "Vega de Tuercespina", x = 35.5, y = 10.6, n = "Entregar: Domina la pantera (Sir S. J. Erlgadin)", q = 191, a = "T" }, { m = 1434, z = "Vega de Tuercespina", x = 35.7, y = 10.8, n = "Entregar: Domina el raptor (Hemet Decautela)", q = 194, a = "T" } } },
