  {
    titulo = "Desolace", min = 37, max = 40,
    entrenar = "Al 38: Aspecto del halcón (rango 4) y Cortar alas (rango 2). Talentos 35-39: Frenesí (los críticos de tu mascota le dan más velocidad de ataque).",
    equipo = "Cambias mucho de equipo en este rango: busca piezas de nivel 35 en la subasta. Al 40 ya podrás llevar malla. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desolace tiene filones de hierro y oro y muchas bestias para desollar (<Cuero pesado>).",
    pasos = {
      { t = "Vuela de Orgrimmar a Sierra Espolón y baja al sur hasta Desolace. En el Puesto del Caminante Fantasma acepta [Khan Dez'hepah] (Felgur Doscortes).", wp = { { m = 1443, z = "Desolace", x = 56.2, y = 59.6, n = "Recoger: Khan Dez'hepah (Felgur Doscortes)", q = 1365, a = "A" } } },
      { t = "Sigue al suroeste hasta el Poblado Sombraprensa: activa el vuelo con Thalon, pon la piedra de hogar con Tabernero Sikewa y acepta [La Mano de Iruxos] (Taiga Melenasabia), [Almejas] (Mai'Lahii) y [La pesca del día] (Nataka Cuerno Largo).", wp = { { m = 1443, z = "Desolace", x = 21.6, y = 74.1, n = "Thalon", npc = 6726 }, { m = 1443, z = "Desolace", x = 24.1, y = 68.2, n = "Tabernero Sikewa", npc = 11106 }, { m = 1443, z = "Desolace", x = 25.8, y = 68.2, n = "Recoger: La Mano de Iruxos (Taiga Melenasabia)", q = 5381, a = "A" }, { m = 1443, z = "Desolace", x = 22.6, y = 72.0, n = "Recoger: Almejas (Mai'Lahii)", q = 6142, a = "A" }, { m = 1443, z = "Desolace", x = 55.4, y = 55.8, n = "Recoger: La pesca del día (Nataka Cuerno Largo)", q = 5386, a = "A" } }, comprobar = { vuelo = "Sombraprensa" } },
      { t = "En la costa del oeste, reúne las almejas para [Almejas]. Para [La pesca del día], lleva dos peces a Nataka Cuerno Largo. Si te faltan, canjea con Jinar'Zillen en Sombraprensa cinco mariscos de las nasas bajo los muelles por cada pez ([Pescado en un balde]). En la fortaleza del Hacha de Trueno, usa el Pico demoníaco sobre el cristal rojo. Recupera la Caja demoníaca y devuelve la caja y el pico a Taiga ([La Mano de Iruxos]).", wp = { { m = 1443, z = "Desolace", x = 33.0, y = 30.3, n = "Objetivo: Almejas", q = 6142, a = "C" }, { m = 1443, z = "Desolace", x = 22.4, y = 73.1, n = "Objetivo: La pesca del día", q = 5386, a = "C" }, { m = 1443, z = "Desolace", x = 55.0, y = 26.6, n = "Objetivo: La Mano de Iruxos", q = 5381, a = "C" }, { m = 1443, z = "Desolace", x = 22.6, y = 72.0, n = "Entregar: Almejas (Mai'Lahii)", q = 6142, a = "T" }, { m = 1443, z = "Desolace", x = 55.4, y = 55.8, n = "Entregar: La pesca del día (Nataka Cuerno Largo)", q = 5386, a = "T" }, { m = 1443, z = "Desolace", x = 25.8, y = 68.2, n = "Entregar: La Mano de Iruxos (Taiga Melenasabia)", q = 5381, a = "T" } } },
      { t = "Al norte del Puesto, en el poblado Kolkar, mata a Khan Dez'hepah, el jefe ([Khan Dez'hepah]). Entrégala y acepta [Colección de orejas]: orejas de los centauros Kolkar de alrededor.", wp = { { m = 1443, z = "Desolace", x = 73.7, y = 45.2, n = "Objetivo: Khan Dez'hepah", q = 1365, a = "C" }, { m = 1443, z = "Desolace", x = 56.2, y = 59.6, n = "Entregar: Khan Dez'hepah (Felgur Doscortes)", q = 1365, a = "T" }, { m = 1443, z = "Desolace", x = 56.2, y = 59.6, n = "Recoger: Colección de orejas (Felgur Doscortes)", q = 1366, a = "A" }, { m = 1443, z = "Desolace", x = 71.6, y = 46.4, n = "Objetivo: Colección de orejas", q = 1366, a = "C" } } },
