  {
    titulo = "Marjal Revolcafango y la montura", min = 40, max = 42,
    entrenar = "Nivel 40: Malla (ya puedes llevarla), Trampa congelante (rango 2), Marca del cazador (rango 3), Golpe de raptor (rango 6) y, para tu mascota, Gruñido (rango 5). Talento 40: Cólera de las bestias (tu mascota hace mucho más daño unos segundos). Es caro: guarda oro también para la montura.",
    equipo = "Al 40 cambia a malla con Agilidad: las recompensas de cuero ya casi no te sirven. Busca en la subasta piezas de malla 'del mono' o 'del tigre'. Al 40 cambia también a <Balas precisas>: en el Poblado Juncobrezo la vende Zanara. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "En el Poblado Juncobrezo, Balai Lok'Wein vende <Primeros auxilios para expertos: Entre vendas>. Desuello y Minería: el Marjal tiene muchas bestias y filones de hierro y mitril.",
    pasos = {
      { t = "Nivel 40: en Orgrimmar entrena con Ormak Tirosiniestro: Malla, Trampa congelante (rango 2), Marca del cazador (rango 3) y Golpe de raptor (rango 6); con Xao'tsu, Gruñido (rango 5) para tu mascota. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1454, z = "Orgrimmar", x = 66.0, y = 18.5, n = "Ormak Tirosiniestro", npc = 3352 }, { m = 1454, z = "Orgrimmar", x = 66.3, y = 14.8, n = "Xao'tsu", npc = 10088 } }, comprobar = { hechizos = { 8737 } } },
      { t = "Montura: vuela a Cima del Trueno y baja al Pueblo Pezuña de Sangre: aprende equitación de kodo con Kar Tormensón y cómprale el kodo a Harb Garrapezuña, al lado.", wp = { { m = 1412, z = "Mulgore", x = 46.8, y = 62.0, n = "Kar Tormensón", npc = 3690 }, { m = 1412, z = "Mulgore", x = 46.6, y = 62.1, n = "Harb Garrapezuña", npc = 3685 } } },
      { t = "Desde El Cruce baja por el camino del sur y, pasado el Puesto del Vigía Lejano del sur, toma el camino del este hasta el Marjal Revolcafango: el Poblado Juncobrezo está al norte del marjal. Activa el vuelo con Shardi y acepta [Los espías de Theramore] (Nazeer Picasangre), [Las pertenencias del Señor Supremo Mok'Morokk] (Señor Supremo Mok'Morkk), [El ejército de los dragones negros] (Tharg) y [Identifica a los cachorros] (Draz'Zilb).", wp = { { m = 1445, z = "Marjal Revolcafango", x = 35.6, y = 31.9, n = "Shardi", npc = 11899 }, { m = 1445, z = "Marjal Revolcafango", x = 35.2, y = 30.7, n = "Recoger: Los espías de Theramore (Nazeer Picasangre)", q = 1201, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 36.3, y = 31.4, n = "Recoger: Las pertenencias del Señor Supremo Mok'Morokk (Señor Supremo Mok'Morkk)", q = 1166, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 37.4, y = 31.4, n = "Recoger: El ejército de los dragones negros (Tharg)", q = 1168, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 37.1, y = 33.1, n = "Recoger: Identifica a los cachorros (Draz'Zilb)", q = 1169, a = "A" } }, comprobar = { vuelo = "Juncobrezo" } },
      { t = "Al norte del Marjal: [¡Qué hambre!] (cabezas de aleta de fango). Alrededor del poblado, los infiltrados de Theramore de [Los espías de Theramore]. Al sur, en las Ciénagas de la Pena: los dragones Pirocabello de [El ejército de los dragones negros], las lenguas y los corazones de los dragones abrasadores de [Identifica a los cachorros] y el grog, el tabaco y la caja de [Las pertenencias del Señor Supremo Mok'Morokk].", wp = { { m = 1445, z = "Marjal Revolcafango", x = 35.1, y = 38.3, n = "Recoger: ¡Qué hambre! (Fangolpe Piesucio)", q = 1177, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 57.7, y = 15.2, n = "Objetivo: ¡Qué hambre!", q = 1177, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 35.1, y = 38.3, n = "Entregar: ¡Qué hambre! (Fangolpe Piesucio)", q = 1177, a = "T" }, { m = 1445, z = "Marjal Revolcafango", x = 40.1, y = 25.1, n = "Objetivo: Los espías de Theramore", q = 1201, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 41.5, y = 66.6, n = "Objetivo: El ejército de los dragones negros", q = 1168, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 44.8, y = 69.5, n = "Objetivo: Identifica a los cachorros", q = 1169, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 39.9, y = 67.1, n = "Objetivo: Las pertenencias del Señor Supremo Mok'Morokk", q = 1166, a = "C" } } },
      { t = "Pantano de la Luz: dale las especias a \"Ojolodo\" Jarl ([Especias calmantes]) y haz [Jarl necesita ojos]: arañas Niebla Negra, al oeste.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Recoger: Especias calmantes (\"Ojolodo\" Jarl)", q = 1218, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Entregar: Especias calmantes (\"Ojolodo\" Jarl)", q = 1218, a = "T" }, { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Recoger: Jarl necesita ojos (\"Ojolodo\" Jarl)", q = 1206, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 32.6, y = 22.1, n = "Objetivo: Jarl necesita ojos", q = 1206, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Entregar: Jarl necesita ojos (\"Ojolodo\" Jarl)", q = 1206, a = "T" } } },
      { t = "Entrega en Juncobrezo [Los espías de Theramore], [El ejército de los dragones negros], [Identifica a los cachorros] y [Las pertenencias del Señor Supremo Mok'Morokk].", wp = { { m = 1445, z = "Marjal Revolcafango", x = 35.2, y = 30.7, n = "Entregar: Los espías de Theramore (Nazeer Picasangre)", q = 1201, a = "T" }, { m = 1445, z = "Marjal Revolcafango", x = 37.4, y = 31.4, n = "Entregar: El ejército de los dragones negros (Tharg)", q = 1168, a = "T" }, { m = 1445, z = "Marjal Revolcafango", x = 37.1, y = 33.1, n = "Entregar: Identifica a los cachorros (Draz'Zilb)", q = 1169, a = "T" }, { m = 1445, z = "Marjal Revolcafango", x = 36.3, y = 31.4, n = "Entregar: Las pertenencias del Señor Supremo Mok'Morokk (Señor Supremo Mok'Morkk)", q = 1166, a = "T" } } },
