      { t = "Vuela a Grom'gol y ve a pie al norte hasta el Bosque del Ocaso; al este, cruza el Paso de la Muerte hasta el Pantano de las Penas. En el Rocal activa el vuelo con Breyk y acepta [Falta de suministros] (Dar), [Carne fresca] (Dar) y [Charca de Lágrimas] (Fel'zerul).", wp = { { m = 1435, z = "Pantano de las Penas", x = 46.1, y = 54.8, n = "Breyk", npc = 6026 }, { m = 1435, z = "Pantano de las Penas", x = 44.7, y = 57.2, n = "Recoger: Falta de suministros (Dar)", q = 698, a = "A" }, { m = 1435, z = "Pantano de las Penas", x = 44.7, y = 57.2, n = "Recoger: Carne fresca (Dar)", q = 1430, a = "A" }, { m = 1435, z = "Pantano de las Penas", x = 47.9, y = 54.8, n = "Recoger: Charca de Lágrimas (Fel'zerul)", q = 1424, a = "A" } }, comprobar = { vuelo = "Rocal" } },
      { t = "En la costa, recoge diez patas de cangrejos monstruosos para [Carne fresca]. Caza crocoliscos adultos hasta reunir ocho flancos para [Falta de suministros]. En la Charca de Lágrimas, recoge diez artefactos Atal'ai para [Charca de Lágrimas]. Evita las patrullas élite o ve en grupo.", wp = { { m = 1435, z = "Pantano de las Penas", x = 95.9, y = 69.1, n = "Objetivo: Carne fresca", q = 1430, a = "C" }, { m = 1435, z = "Pantano de las Penas", x = 55.1, y = 52.8, n = "Objetivo: Falta de suministros", q = 698, a = "C" }, { m = 1435, z = "Pantano de las Penas", x = 70.4, y = 50.4, n = "Objetivo: Charca de Lágrimas", q = 1424, a = "C" }, { m = 1435, z = "Pantano de las Penas", x = 44.7, y = 57.2, n = "Entregar: Carne fresca (Dar)", q = 1430, a = "T" }, { m = 1435, z = "Pantano de las Penas", x = 81.3, y = 81.0, n = "Entregar: Falta de suministros (Tok'Kar)", q = 698, a = "T" }, { m = 1435, z = "Pantano de las Penas", x = 47.9, y = 54.8, n = "Entregar: Charca de Lágrimas (Fel'zerul)", q = 1424, a = "T" } } },
      { t = "Nivel 44: entrena con Ogromm en el Rocal: Disparo de puntería (rango 4), Disparo Arcano (rango 6), Aliviar mascota (rango 5) y Mordedura de mangosta (rango 3). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1435, z = "Pantano de las Penas", x = 47.3, y = 53.4, n = "Ogromm", npc = 987 } }, comprobar = { hechizos = { 20902 } } },
