      { t = "Bandidos Errantes al este de Gadgetzan para las dos misiones; después [Más justicia para bandidos].", wp = { { m = 1446, z = "Tanaris", x = 63.5, y = 31.1, n = "Objetivo: Justicia para bandidos", q = 1690, a = "C" }, { m = 1446, z = "Tanaris", x = 52.5, y = 28.5, n = "Entregar: Justicia para bandidos (Ingeniero jefe Pasaquillas)", q = 1690, a = "T" }, { m = 1446, z = "Tanaris", x = 52.5, y = 28.4, n = "Entregar: Cazador de bolsas de agua (Grifoperador Llantalunket)", q = 1707, a = "T" }, { m = 1446, z = "Tanaris", x = 52.5, y = 28.5, n = "Recoger: Más justicia para bandidos (Ingeniero jefe Pasaquillas)", q = 1691, a = "A" }, { m = 1446, z = "Tanaris", x = 62.0, y = 37.4, n = "Objetivo: Más justicia para bandidos", q = 1691, a = "C" }, { m = 1446, z = "Tanaris", x = 52.5, y = 28.5, n = "Entregar: Más justicia para bandidos (Ingeniero jefe Pasaquillas)", q = 1691, a = "T" } } },
