R.profesiones = {
  { nombre = "Minería", skill = 186, icono = "Interface\\Icons\\Trade_Mining", intro = "Mina cada veta que veas: da puntos y oro para los entrenamientos. Fundir en una forja también da puntos. Rangos: aprendiz con Vartha Rockmane en el Campamento Narache (también vende el <Pico de minero>); oficial, experto y artesano con Brek Pezuñapétrea en Cima del Trueno o con Makaru en Orgrimmar (50 y nivel 10; 125 y nivel 20; 200 y nivel 25).", pasos = {
