    { d = 65, h = 125, icono = "Interface\\Icons\\inv_ore_tin_01", t = "<Mineral de estaño> y <Mineral de plata>: vetas de estaño y de plata en Los Baldíos, Sierra Espolón y Vallefresno. Funde <Lingote de estaño> (1 <Mineral de estaño>), <Lingote de plata> (1 <Mineral de plata>) y <Lingote de bronce> (1 <Lingote de cobre> y 1 <Lingote de estaño>). A 125 aprende el rango experto.", crea = { 2771, 3576, 2842, 2841 } },
    { d = 125, h = 175, icono = "Interface\\Icons\\inv_ore_iron_01", t = "<Hierro> y <Mineral de oro>: filones de hierro y de oro en Desolace, Las Mil Agujas, la Vega de Tuercespina y Arathi. Funde <Lingote de hierro> (1 <Hierro>) y <Lingote de oro> (1 <Mineral de oro>).", crea = { 2772, 3575, 3577 } },
    { d = 175, h = 250, icono = "Interface\\Icons\\inv_ore_mithril_02", t = "<Mineral de mitril>: filones de mitril en Tanaris, Feralas, las Tierras del Interior y las Tierras Inhóspitas. Funde <Lingote de mitril> (1 <Mineral de mitril>). A 200 aprende el rango artesano. Desde 230 también la veraplata: <Lingote de veraplata> (1 <Veraplata>).", crea = { 3858, 3860, 6037 } },
    { d = 250, h = 300, icono = "Interface\\Icons\\inv_ore_thorium_02", t = "<Torio>: vetas pequeñas de torio en Un'Goro, Frondavil, Cuna del Invierno y las Tierras de la Peste; desde 275, también las ricas. Funde <Lingote de torio> (1 <Torio>).", crea = { 10620, 12359 } },
  } },
  { nombre = "Desuello", skill = 393, icono = "Interface\\Icons\\INV_Misc_Pelt_Wolf_01", intro = "Desuella todas las bestias que mates: el cuero se vende bien. Las de nivel 10 o menos valen desde el principio; después, nivel 20 pide 100, nivel 30 pide 150, nivel 40 pide 200 y así hasta 300. Rangos: aprendiz con Nawka Wildsong en el Campamento Narache (también vende el <Cuchillo para desollar>); oficial, experto y artesano con Thuwd en Orgrimmar (50 y nivel 10; 125 y nivel 20; 200 y nivel 25).", pasos = {
    { d = 1, h = 75, icono = "Interface\\Icons\\inv_misc_leatherscrap_03", t = "<Cuero ligero> y <Restos de cuero estropeado>: zancudos, lobos, pumas y jabaguerreros de Mulgore y bestias del norte de Los Baldíos. A 50 aprende el rango oficial con Mooranta en Cima del Trueno o con Thuwd en Orgrimmar.", crea = { 2318 } },
    { d = 75, h = 150, icono = "Interface\\Icons\\inv_misc_leatherscrap_05", t = "<Cuero medio>: bestias de Los Baldíos, Sierra Espolón y Vallefresno. A 125 aprende el rango experto con Thuwd.", crea = { 2319 } },
    { d = 150, h = 225, icono = "Interface\\Icons\\inv_misc_leatherscrap_07", t = "<Cuero pesado>: bestias de Las Mil Agujas, Desolace, la Vega de Tuercespina, Arathi y el Marjal Revolcafango. A 200 aprende el rango artesano.", crea = { 4234 } },
    { d = 225, h = 300, icono = "Interface\\Icons\\inv_misc_leatherscrap_08", t = "<Cuero grueso> y después <Cuero basto>: bestias de Tanaris, Feralas, las Tierras del Interior, Un'Goro y Cuna del Invierno.", crea = { 4304 } },
  } },
  { nombre = "Primeros auxilios", skill = 129, icono = "Interface\\Icons\\Spell_Holy_SealOfSacrifice", intro = "No ocupa una de tus dos profesiones y en Forever también hace pociones de curación. Instructores: Vira Pezuña Joven en el Pueblo Pezuña de Sangre, Pand Amarrapiedra en Cima del Trueno y Arnok en Orgrimmar. A 125 compra <Primeros auxilios para expertos: Entre vendas> a Balai Lok'Wein en el Poblado Juncobrezo (Marjal Revolcafango). A 225 haz [Orden de gravedad] con Doctor Gregory Victor en Sentencia (Arathi, nivel 35).", pasos = {
