    { d = 150, h = 180, icono = "Interface\\Icons\\inv_misc_bandage_01", t = "<Venda de seda> (1 <Paño de seda>).", mat = { { 4306, 1, "Paño de seda" } }, crea = { 6450 } },
    { d = 180, h = 210, icono = "Interface\\Icons\\inv_misc_bandage_02", t = "<Venda de seda pesada> (2 <Paño de seda>).", mat = { { 4306, 2, "Paño de seda" } }, crea = { 6451 } },
    { d = 210, h = 225, icono = "Interface\\Icons\\inv_misc_bandage_19", t = "<Venda de paño mágico> (1 <Tela de paño mágico>). A 225 haz [Orden de gravedad]: sin ella no pasas.", mat = { { 4338, 1, "Tela de paño mágico" } }, crea = { 8544 } },
    { d = 225, h = 240, icono = "Interface\\Icons\\inv_potion_53", t = "<Poción de curación excelente> (<Solea>, <Especias calmantes> y <Vial de cristal>) si consigues la receta (cae de enemigos); si no, <Venda de paño mágico>.", mat = { { 8838, 1, "Solea" }, { 3713, 1, "Especias calmantes" }, { 8925, 1, "Vial de cristal" } }, crea = { 3928 } },
